using System.Net;
using BARANG.Core.Domain.Files;
using BARANG.Core.Domain.Organization;
using BARANG.Core.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
using Npgsql;
using Xunit;

namespace BARANG.Core.IntegrationTests.Database;

[Collection(PostgreSqlDatabaseFixture.CollectionName)]
public sealed class ArtworkFileFoundationTests(PostgreSqlDatabaseFixture database)
{
    [Fact]public async Task MigrationCreatesAllTablesPermissionsAndRls(){await database.ResetAsync(TestContext.Current.CancellationToken);await using CoreDbContext db=database.CreateAdministrationCoreDbContext();string[]tables=await db.Database.SqlQueryRaw<string>("SELECT table_name AS \"Value\" FROM information_schema.tables WHERE table_schema='barang' AND table_name IN ('artworks','artwork_versions','artwork_tags','artwork_tag_assignments','stored_files','file_versions','file_links','file_processing_jobs','file_derivatives')").ToArrayAsync(TestContext.Current.CancellationToken);Assert.Equal(9,tables.Length);Assert.Equal(5,await db.Permissions.CountAsync(x=>x.Code=="artwork.read"||x.Code=="artwork.manage"||x.Code=="file.read"||x.Code=="file.manage"||x.Code=="file.upload",TestContext.Current.CancellationToken));}
    [Fact]public async Task ArtworkRlsAndPoolContextPreventCompanyLeakage(){await database.ResetAsync(TestContext.Current.CancellationToken);Guid a=Guid.NewGuid(),b=Guid.NewGuid(),artworkB=Guid.NewGuid();DateTimeOffset now=DateTimeOffset.UtcNow;await using(CoreDbContext db=database.CreateAdministrationCoreDbContext()){db.Companies.AddRange(Company.Create(a,"FILE_A","A",now).Value,Company.Create(b,"FILE_B","B",now).Value);db.Artworks.AddRange(Artwork.Create(Guid.NewGuid(),a,"A-1","A",null,null,null,now).Value,Artwork.Create(artworkB,b,"B-1","B",null,null,null,now).Value);db.ArtworkTags.Add(ArtworkTag.Create(Guid.NewGuid(),b,"PRIVATE","Private",now).Value);await db.SaveChangesAsync(TestContext.Current.CancellationToken);}await using NpgsqlConnection c=new(database.ConnectionString);await c.OpenAsync(TestContext.Current.CancellationToken);Assert.Equal((1L,0L),await Counts(c,a));Assert.Equal((1L,1L),await Counts(c,b));Assert.Equal((0L,0L),await Counts(c,null));await using NpgsqlTransaction tx=await c.BeginTransactionAsync(TestContext.Current.CancellationToken);await using NpgsqlCommand set=new("SELECT set_config('barang.company_id',@company,true)",c,tx);set.Parameters.AddWithValue("company",a.ToString());await set.ExecuteNonQueryAsync(TestContext.Current.CancellationToken);await using NpgsqlCommand update=new("UPDATE barang.artworks SET title='forbidden' WHERE id=@id",c,tx);update.Parameters.AddWithValue("id",artworkB);Assert.Equal(0,await update.ExecuteNonQueryAsync(TestContext.Current.CancellationToken));await tx.RollbackAsync(TestContext.Current.CancellationToken);}
    [Fact]public async Task FileAndArtworkEndpointsRejectAnonymousCallers(){await database.ResetAsync(TestContext.Current.CancellationToken);await using PostgreSqlCoreApiFactory factory=new(database.ConnectionString);using HttpClient client=factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await client.GetAsync("/api/v1/artworks",TestContext.Current.CancellationToken)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.PostAsync("/api/v1/files/upload",null,TestContext.Current.CancellationToken)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await client.GetAsync($"/api/v1/files/{Guid.NewGuid()}/versions/{Guid.NewGuid()}/download",TestContext.Current.CancellationToken)).StatusCode);}
    private static async Task<(long Artworks,long Tags)>Counts(NpgsqlConnection c,Guid?company){await using NpgsqlTransaction tx=await c.BeginTransactionAsync(TestContext.Current.CancellationToken);if(company is not null){await using NpgsqlCommand set=new("SELECT set_config('barang.company_id',@company,true)",c,tx);set.Parameters.AddWithValue("company",company.Value.ToString());await set.ExecuteNonQueryAsync(TestContext.Current.CancellationToken);}async Task<long>Count(string table){await using NpgsqlCommand command=new($"SELECT count(*) FROM barang.{table}",c,tx);return Convert.ToInt64(await command.ExecuteScalarAsync(TestContext.Current.CancellationToken),System.Globalization.CultureInfo.InvariantCulture);}var result=(await Count("artworks"),await Count("artwork_tags"));await tx.RollbackAsync(TestContext.Current.CancellationToken);return result;}
}
